mapper.insert:
insert into lesson 
(cate, cate0, cate1, cate2, cate3, cate4, subcate, represent, title, lesson, description, contentimg, careerDB
, subcate0, price1, price2, price3
, subcate1, opt1price1, opt1price2, opt1price3
, subcate2, opt2price1, opt2price2, opt2price3
, subcate3, opt3price1, opt3price2, opt3price3
, subcate4, opt4price1, opt4price2, opt4price3
, prinegotiation, email, postingdate, readcount, day, gawe, trial, visible) 
values 
(#{cate}, #{cate0}, #{cate1}, #{cate2}, #{cate3}, #{cate4}, #{subCate}, #{represent}, #{title}, #{lesson}, #{description}, #{contentimg}, #{careerDB}
, #{subCate0}, #{price1}, #{price2},#{price3}
, #{subCate1}, #{opt1price1}, #{opt1price2},#{opt1price3}
, #{subCate2}, #{opt2price1}, #{opt2price2},#{opt2price3}
, #{subCate3}, #{opt3price1}, #{opt3price2}, #{opt3price3}
, #{subCate4}, #{opt4price1}, #{opt4price2}, #{opt4price3}
, #{priNegotiation}, #{email}, #{postingdate}, #{readCount}, #{day}, #{gawe}, #{trial}, 1)

mapper.select:
select A.nickname, A.email, A.birth, B.imgpath, B.universe, B.univsub, B.academy, B.academyd, B.sexual, B.career,B.certify, C.subcate, C.represent, C.title, C.subcate0, C.price1, C.price2, C.price3, C.subcate1, C.opt1price1, C.opt1price2, C.opt1price3 , C.subcate2, C.opt2price1, C.opt2price2, C.opt2price3 , C.subcate3, C.opt3price1, C.opt3price2, C.opt3price3 , C.subcate4, C.opt4price1, C.opt4price2, C.opt4price3 , C.prinegotiation, C.visible, C.id, C.readcount from members as A, profile as B, lesson as C where A.email=B.email and B.email=C.email and C.visible=1
and C.cate like concat('%',#{subject},'%') order by A.membership desc, C.readcount desc limit #{firstRow}, #{endRow}
and C.subcate like concat('%',#{subject},'%') and C.subcate not like concat('%','중국어','%') order by A.membership desc, C.readcount desc limit #{firstRow}, #{endRow}
and C.subcate like concat('%',#{subject},'%') order by A.membership desc, C.readcount desc limit #{firstRow}, #{endRow}

select 
A.nickname, A.email, A.birth, 
B.imgpath, B.universe, B.univsub, B.academy, B.academyd, B.sexual, B.career,B.certify, 
C.subcate, C.represent, C.title, 
C.subcate0, C.price1, C.price2, C.price3, 
C.subcate1, C.opt1price1, C.opt1price2, C.opt1price3, 
C.subcate2, C.opt2price1, C.opt2price2, C.opt2price3,
C.subcate3, C.opt3price1, C.opt3price2, C.opt3price3,
C.subcate4, C.opt4price1, C.opt4price2, C.opt4price3,
C.prinegotiation, C.visible, C.id, C.readcount
from members as A, profile as B, lesson as C where A.email=B.email and B.email=C.email and C.visible=1 and B.locales like concat('%',#{locale},'%') and B.career>=#{career} 
 and B.sexual like concat('%',#{sexual},'%')


	 	and C.cate like concat('%',#{subject},'%')  order by A.membership desc, C.id desc limit #{firstRow}, #{endRow}


	 	and C.subcate like concat('%',#{subject},'%') and C.subcate not like concat('%','중국어','%') order by A.membership desc, C.id desc limit #{firstRow}, #{endRow}




	 	and C.cate like concat('%',#{subject},'%')  order by A.membership desc, C.readcount desc limit #{firstRow}, #{endRow}


	 	and C.subcate like concat('%',#{subject},'%') and C.subcate not like concat('%','중국어','%')  order by A.membership desc, C.readcount desc limit #{firstRow}, #{endRow}



	 	and C.subcate like concat('%',#{subject},'%')  order by A.membership desc, C.id desc limit #{firstRow}, #{endRow}



	 	and C.subcate like concat('%',#{subject},'%')  order by A.membership desc, C.readcount desc limit #{firstRow}, #{endRow}

		select A.email, A.name ,A.nickname, A.phone ,B.sexual, C.represent, C.title, C.cate, C.subcate, C.gawe, C.trial, C.visible ,


   		     C.cate0, C.subCate0, C.price1, C.price2, C.price3 from members as A, profile as B, lesson as C where A.email=#{email} and B.email=#{email} and C.id=#{id}


   		     C.cate1, C.subCate1, C.opt1price1, C.opt1price2, C.opt1price3 from members as A, profile as B, lesson as C where A.email=#{email} and B.email=#{email} and C.id=#{id}


   		     C.cate2, C.subCate2, C.opt2price1, C.opt2price2, C.opt2price3 from members as A, profile as B, lesson as C where A.email=#{email} and B.email=#{email} and C.id=#{id}


   		     C.cate3, C.subCate3, C.opt3price1, C.opt3price2, C.opt3price3 from members as A, profile as B, lesson as C where A.email=#{email} and B.email=#{email} and C.id=#{id}


   		     C.cate4, C.subCate4, C.opt4price1, C.opt4price2, C.opt4price3 from members as A, profile as B, lesson as C where A.email=#{email} and B.email=#{email} and C.id=#{id}
